## Fase E — Mini‑RSA en Python (en la web)
**Objetivo:** funciones modulares y cifrado/descifrado de **texto** (por caracteres).


```{pyodide}
# Setup mínimo (puedes copiar de Fase D o usar estas funciones)
def egcd(a,b):
    if b==0: return (a,1,0)
    g,x1,y1 = egcd(b, a%b)
    return (g, y1, x1 - (a//b)*y1)

def modinv(a,m):
    g,x,_ = egcd(a,m)
    if g!=1: raise ValueError("No hay inverso")
    return x % m

from math import gcd

def build_keys(p=17,q=23):
    n=p*q; phi=(p-1)*(q-1)
    for e in [3,5,7,11,17,257]:
        if gcd(e,phi)==1: break
    d=modinv(e,phi)
    return (n,e),(n,d)

def enc_int(m,pub):
    n,e=pub
    if not (0<=m<n): raise ValueError("m fuera de rango")
    return pow(m,e,n)

def dec_int(c,priv):
    n,d=priv
    return pow(c,d,n)

def t2i(s): return [ord(ch) for ch in s]

def i2t(v): return "".join(chr(x) for x in v)

def enc_text(s,pub):
    n,_=pub
    a=t2i(s)
    if any(x>=n for x in a):
        raise ValueError("Algún carácter ≥ n; usa primos algo mayores o mensaje más simple")
    return [enc_int(x,pub) for x in a]

def dec_text(lst,priv):
    return i2t([dec_int(x,priv) for x in lst])

pub,priv=build_keys()
msg="Hola 2ESO!"  # cámbialo
C=enc_text(msg,pub)
R=dec_text(C,priv)
print("pub:",pub,"priv:",priv)
print("Cifrado:",C)
print("Recuperado:",R)
```


**Entregable:** pruebas con 2–3 mensajes + explicación.
